<?php require_once __DIR__.'/includes/functions.php';need_login();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id_notifikasi']??0);if($id>0)db()->prepare('UPDATE notifications SET is_read=1 WHERE id_notifikasi=? AND id_pengguna=?')->execute([$id,me()['id_user']]);else db()->prepare('UPDATE notifications SET is_read=1 WHERE id_pengguna=?')->execute([me()['id_user']]);flash('success','Notifikasi diperbarui.');go('/laporwarga/notifikasi.php');}$s=db()->prepare('SELECT * FROM notifications WHERE id_pengguna=? ORDER BY created_at DESC LIMIT 100');$s->execute([me()['id_user']]);$rows=$s->fetchAll();header_page('Notifikasi');?><h1>Notifikasi</h1><form method="post"><?=csrf_input()?><button class="btn outline">Tandai semua dibaca</button></form><?php if(!$rows):?><div class="empty">Belum ada notifikasi.</div><?php endif;?><?php foreach($rows as $n):?><article class="card"><div class="row-between"><b><?=e($n['judul'])?></b><?php if(!$n['is_read']):?><span class="badge">Baru</span><?php endif;?></div><p><?=nl2br(e($n['pesan']))?></p><small><?=e($n['created_at'])?></small><p><?php if($n['link_tujuan']):?><a class="btn small outline" href="<?=e($n['link_tujuan'])?>">Buka</a><?php endif;?><?php if(!$n['is_read']):?> <form class="inline" method="post"><?=csrf_input()?><input type="hidden" name="id_notifikasi" value="<?=$n['id_notifikasi']?>"><button class="linkbtn">Tandai dibaca</button></form><?php endif;?></p></article><?php endforeach;?><?php footer_page();?>